// // // // // // // // // // // //         displayNames: displayNames,
// // // // // // // // // // // //       ),
// // // // // // // // // // // //       TodTurnPhase.awaitingResult => _CardView(
// // // // // // // // // // // //         state: state,
// // // // // // // // // // // //         game: game,
// // // // // // // // // // // //         displayNames: displayNames,
// // // // // // // // // // // //       ),
// // // // // // // // // // // //       _ => _ChoiceView(state: state, game: game, displayNames: displayNames),
// // // // // // // // // // // //     };
// // // // // // // // // // // //   }
// // // // // // // // // // // // }

