}

class _CardView extends StatelessWidget {
  const _CardView({
    required this.state,
    required this.game,
    required this.displayNames,
  });
  final TodState state;
  final TodGameProvider game;
  final Map<String, String> displayNames;

  @override
  Widget build(BuildContext context) {
    final theme = context.theme;
    final card = state.currentCard;
    final isMyTurn = game.isMyTurn;

    if (card == null) {
      return const Center(child: Text('No card available — all cards used!'));
    }

    final isSpicy = card.difficulty == TodDifficulty.spicy;
    final isTruth = card.type == TodCardType.truth;
    final cardColor = isTruth ? AppColors.truthColor : AppColors.dareColor;
    final playerName =
        displayNames[state.currentPlayerId] ??
        'Player ${state.currentPlayerId.substring(0, 4)}';

    return Padding(
      padding: const EdgeInsets.all(20),
      child: Column(
        children: [
          TodPlayerBanner(
            playerId: state.currentPlayerId,
            playerName: playerName,
            playerOrder: state.playerOrder,
            isMyTurn: isMyTurn,
          ),
          const SizedBox(height: 12),
          if (game.timerIsRunning || game.timerRemaining > 0)
            Padding(
              padding: const EdgeInsets.only(bottom: 12),
              child: TodTimerRing(
                remaining: game.timerRemaining,
                total: game.state != null ? (80) : 60,
                color: cardColor,
              ).animate().fadeIn(),
            ),
          Expanded(
            child: _CardFace(
              card: card,
              cardColor: cardColor,
              isSpicy: isSpicy,
              isTruth: isTruth,
              coverUrl: game.packCoverUrl,
            ),
          ),
          const SizedBox(height: 20),
          if (isMyTurn) ...[
            JButton(
              label: 'Done! ✅',
              onPressed: () =>
                  _showCompleteSheet(context, game, isTruth: isTruth),
            ),
            // Previously shown unconditionally — the room's "Allow Skip"
            // setting was persisted but never actually consulted anywhere.
            // Also hidden entirely when punishment mode is off, per the
            // room-owner setting: with no punishment to enforce it,
            // skipping isn't offered as a choice at all.
            if ((game.config?.allowSkip ?? true) &&
                (game.config?.enablePunishments ?? false)) ...[
              const SizedBox(height: 10),
              TextButton(
                onPressed: () => _confirmSkip(context),
                child: Text(
                  'Skip',
                  style: TextStyle(
                    color: theme.colorScheme.onSurfaceVariant,
                    fontWeight: FontWeight.w600,
                  ),
                ),
              ),
            ],
          ] else
            _PeerActivityIndicator(
              playerName: playerName,
              activity: game.peerActivityLabel,
            ),
          if (game.canAdvanceTurnHere && !isMyTurn)
            Padding(
              padding: const EdgeInsets.only(top: 6),
              child: TextButton.icon(
                // Gated on canAdvanceTurnHere (advance_turn/skip_turn
                // specifically), not the broader canModerate — a moderator
                // with neither permission previously still saw this button,
                // but tapping it was a silent no-op since the owner-side
                // check already required one of those two keys. Delegates
                // to the owner's client if the presser isn't the owner — a
                // direct game.ownerAdvanceTurn call here would silently
                // no-op for a non-owner moderator.
                onPressed: () => game.requestAdvanceTurn(force: true),
                icon: const Icon(Icons.skip_next_rounded, size: 16),
                label: const Text('Skip turn (mod)'),
                style: TextButton.styleFrom(
                  foregroundColor: AppColors.warningAmber,
                ),
              ),
            ),
        ],
      ),
    );
  }

  void _showCompleteSheet(
    BuildContext context,
    TodGameProvider game, {
    bool isTruth = false,
  }) {
    final ctrl = TextEditingController();
    String? imgB64;
    bool attempted = false;

    Uint8List? voiceBytes;
    bool isRecording = false;
    final recorder = AudioRecorder();
    bool recorderDisposed = false;
    void safeDisposeRecorder() {
      if (recorderDisposed) return;
      recorderDisposed = true;
      recorder.dispose().catchError((_) {});
    }

    Timer? recordingTimer;
    int recordingSeconds = 0;
    final isPremium =
        context.read<AuthProvider>().currentUser?.isPremiumActive ?? false;
    final maxRecordSeconds = isPremium ? 60 : 30;

    game.pauseTimer();
    game.broadcastActivity('answering');

    Future<void> stopRecording(StateSetter setS) async {
      recordingTimer?.cancel();
      final path = await recorder.stop();
      if (path == null) return;
      await Future.delayed(const Duration(milliseconds: 300));
      final file = File(path);
      if (!await file.exists()) return;
      final bytes = await file.readAsBytes();
      if (bytes.isEmpty) return;
      setS(() {
        voiceBytes = bytes;
        isRecording = false;
        recordingSeconds = 0;
      });
    }

    Future<void> startRecording(StateSetter setS) async {
      if (!await recorder.hasPermission()) return;
      game.broadcastActivity('uploading_proof');
      final dir = await getTemporaryDirectory();
      final path =
          '${dir.path}/proof_${DateTime.now().millisecondsSinceEpoch}.m4a';
      await recorder.start(
        const RecordConfig(
          encoder: AudioEncoder.aacLc,
          bitRate: 64000,
          sampleRate: 44100,
        ),
        path: path,
      );
      recordingSeconds = 0;
      setS(() {
        isRecording = true;
        imgB64 = null;
      });
      recordingTimer = Timer.periodic(const Duration(seconds: 1), (_) {
        recordingSeconds++;
        setS(() {});
        if (recordingSeconds >= maxRecordSeconds) stopRecording(setS);
      });
    }

    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setS) {
          return PopScope(
            onPopInvoked: (_) {
              recordingTimer?.cancel();
              safeDisposeRecorder();
            },
            child: Padding(
              padding: EdgeInsets.only(
                bottom: MediaQuery.of(ctx).viewInsets.bottom,
              ),
              child: Container(
                padding: const EdgeInsets.all(20),
                decoration: BoxDecoration(
                  color: Theme.of(ctx).colorScheme.surface,
                  borderRadius: const BorderRadius.vertical(
                    top: Radius.circular(20),
                  ),
                ),
                child: SingleChildScrollView(
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      Center(
                        child: Container(
                          width: 36,
                          height: 4,
                          decoration: BoxDecoration(
                            color: Colors.grey.shade300,
                            borderRadius: BorderRadius.circular(2),
                          ),
                        ),
                      ),
                      const SizedBox(height: 16),
                      Row(
                        children: [
                          Text(
                            isTruth ? '🤔 Truth' : '🔥 Dare',
                            style: Theme.of(ctx).textTheme.labelLarge?.copyWith(
                              color: isTruth
                                  ? AppColors.truthColor
                                  : AppColors.dareColor,
                              fontWeight: FontWeight.w700,
                            ),
                          ),
                          const SizedBox(width: 8),
                          Text(
                            'Complete Turn',
                            style: Theme.of(ctx).textTheme.titleMedium
                                ?.copyWith(fontWeight: FontWeight.w700),
                          ),
                        ],
                      ),
                      const SizedBox(height: 12),
                      TextField(
                        controller: ctrl,
                        maxLines: 3,
                        maxLength: 300,
                        decoration: InputDecoration(
                          hintText: isTruth
                              ? 'Your answer is required…'
                              : 'Add a description (optional)…',
                          border: const OutlineInputBorder(),
                          errorText:
                              isTruth && ctrl.text.trim().isEmpty && attempted
                              ? 'Truth requires a response'
                              : null,
                        ),
                        onChanged: (_) => setS(() {}),
                      ),
                      const SizedBox(height: 8),
                      if (!isTruth) ...[
                        if (imgB64 != null)
                          Stack(
                            children: [
                              ClipRRect(
                                borderRadius: BorderRadius.circular(8),
                                child: Image.memory(
                                  base64Decode(imgB64!),
                                  height: 120,
                                  width: double.infinity,
                                  fit: BoxFit.cover,
                                ),
                              ),
                              Positioned(
                                top: 4,
                                right: 4,
                                child: GestureDetector(
                                  onTap: () => setS(() => imgB64 = null),
                                  child: const CircleAvatar(
                                    radius: 12,
                                    backgroundColor: Colors.black54,
                                    child: Icon(
                                      Icons.close,
                                      size: 14,
                                      color: Colors.white,
                                    ),
                                  ),
                                ),
                              ),
                            ],
                          )
                        else if (voiceBytes != null)
                          Container(
                            padding: const EdgeInsets.symmetric(
                              horizontal: 12,
                              vertical: 10,
                            ),
                            decoration: BoxDecoration(
                              color: Colors.purple.shade50,
                              borderRadius: BorderRadius.circular(8),
                              border: Border.all(color: Colors.purple.shade300),
                            ),
                            child: Row(
                              children: [
                                const Icon(
                                  Icons.check_circle_rounded,
                                  color: Colors.purple,
                                ),
                                const SizedBox(width: 8),
                                const Expanded(
                                  child: Text(
                                    'Voice proof recorded',
                                    style: TextStyle(
                                      color: Colors.purple,
                                      fontWeight: FontWeight.w600,
                                    ),
                                  ),
                                ),
                                IconButton(
                                  tooltip: 'Preview',
                                  icon: const Icon(
                                    Icons.play_circle_outline,
                                    color: Colors.purple,
                                  ),
                                  onPressed: () => showModalBottomSheet(
                                    context: ctx,
                                    backgroundColor: Colors.transparent,
                                    builder: (_) => _VoicePlayerSheet(
                                      voiceB64: base64Encode(voiceBytes!),
                                    ),
                                  ),
                                ),
                                IconButton(
                                  icon: const Icon(
                                    Icons.delete_outline,
                                    color: Colors.red,
                                    size: 18,
                                  ),
                                  onPressed: () =>
                                      setS(() => voiceBytes = null),
                                ),
                              ],
                            ),
                          )
                        else if (isRecording)
                          _RecordingWidget(
                            seconds: recordingSeconds,
                            maxSeconds: maxRecordSeconds,
                            onStop: () => stopRecording(setS),
                          )
                        else
                          Row(
                            children: [
                              Expanded(
                                child: OutlinedButton.icon(
                                  onPressed: () async {
                                    try {
                                      game.broadcastActivity(
                                        'uploading_proof',
                                      );
                                      final picked = await ImagePicker()
                                          .pickImage(
                                            source: ImageSource.gallery,
                                            imageQuality: 40,
                                          );
                                      if (picked != null) {
                                        final bytes = await picked
                                            .readAsBytes();
                                        setS(
                                          () => imgB64 = base64Encode(bytes),
                                        );
                                      }
                                    } catch (_) {}
                                  },
                                  icon: const Icon(
                                    Icons.add_photo_alternate_outlined,
                                  ),
                                  label: const Text('Photo'),
                                ),
                              ),
                              const SizedBox(width: 8),
                              Expanded(
                                child: OutlinedButton.icon(
                                  onPressed: () => startRecording(setS),
                                  icon: const Icon(Icons.mic_outlined),
                                  label: Text(
                                    'Voice (max ${maxRecordSeconds}s)',
                                  ),
                                ),
                              ),
                            ],
                          ),
                        const SizedBox(height: 8),
                      ],
                      const SizedBox(height: 8),
                      FilledButton(
                        onPressed: () {
                          if (isTruth && ctrl.text.trim().isEmpty) {
                            setS(() => attempted = true);
                            return;
                          }
                          final voiceB64 = voiceBytes != null
                              ? base64Encode(voiceBytes!)
                              : '';
                          recordingTimer?.cancel();
                          safeDisposeRecorder();
                          Navigator.of(ctx).pop();
                          game.broadcastActivity('waiting_for_approval');
                          final cfg = game.config;
                          game.completeTurn(
                            response: ctrl.text.trim(),
                            proofImageB64: imgB64 ?? '',
                            proofVoiceB64: voiceB64,
                            proofViewSeconds: cfg?.proofViewSeconds ?? 5,
                            proofViewMode: cfg?.proofReplayMode == 'replay_once'
                                ? TodProofViewMode.replayOnce
                                : TodProofViewMode.once,
                            proofVisibility: TodProofVisibilitySettings(
                              visibility: switch (cfg?.proofVisibilityPolicy) {
                                'players_only' => TodProofVisibility.playersOnly,
                                'spectators_only' =>
                                  TodProofVisibility.spectatorsOnly,
                                _ => TodProofVisibility.everyone,
                              },
                            ),
                          );
                        },
                        child: const Text('Submit & Complete Turn ✅'),
                      ),
                      const SizedBox(height: 4),
                      TextButton(
                        onPressed: () {
                          recordingTimer?.cancel();
                          safeDisposeRecorder();
                          Navigator.of(ctx).pop();
                        },
                        child: const Text('Cancel'),
                      ),
                    ],
                  ),
                ),
              ),
            ),
          );
        },
      ),
    ).then((_) {
      game.resumeTimer();
    });
  }

  Future<void> _confirmSkip(BuildContext context) async {
    final confirmed = await showConfirmDialog(
      context: context,
      title: 'Skip this card?',
      message: 'Skipping may result in a group punishment vote.',
      confirmLabel: 'Skip',
    );
    if (confirmed == true) game.skipTurn();
  }
}

class _CardFace extends StatelessWidget {
  const _CardFace({
    required this.card,
    required this.cardColor,
    required this.isSpicy,
    required this.isTruth,
    this.coverUrl,
  });

  final TodCard card;
  final Color cardColor;
  final bool isSpicy;
  final bool isTruth;
  final String? coverUrl;

  @override
  Widget build(BuildContext context) {
    final hasCover = coverUrl != null && coverUrl!.isNotEmpty;
    return ClipRRect(
      borderRadius: BorderRadius.circular(24),
      child: Container(
        width: double.infinity,
        constraints: const BoxConstraints.expand(),
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(24),
          border: Border.all(color: cardColor.withOpacity(0.55), width: 1.5),
          boxShadow: [
            BoxShadow(
              color: cardColor.withOpacity(0.38),
              blurRadius: 24,
              offset: const Offset(0, 8),
            ),
            BoxShadow(
              color: Colors.black.withOpacity(0.25),
              blurRadius: 10,
              offset: const Offset(0, 3),
            ),
          ],
        ),
        child: Stack(
          children: [
            Positioned.fill(
              child: hasCover
                  ? Image.network(
                      coverUrl!,
                      fit: BoxFit.cover,
                      width: double.infinity,
                      height: double.infinity,
                      errorBuilder: (_, __, ___) => Image.asset(
                        'assets/images/jma3a_card_background.png',
                        fit: BoxFit.cover,
                        width: double.infinity,
                        height: double.infinity,
                      ),
                    )
                  : Image.asset(
                      'assets/images/jma3a_card_background.png',
                      fit: BoxFit.cover,
                      width: double.infinity,
                      height: double.infinity,
                      errorBuilder: (_, __, ___) => Container(
                        decoration: BoxDecoration(
                          gradient: LinearGradient(
                            colors: [cardColor, cardColor.withOpacity(0.78)],
                            begin: Alignment.topLeft,
                            end: Alignment.bottomRight,
                          ),
                        ),
                      ),
                    ),
            ),
            Positioned.fill(
              child: Container(
                decoration: BoxDecoration(
                  gradient: LinearGradient(
                    colors: [
                      cardColor.withOpacity(0.45),
                      const Color(0xFF0D1B2A).withOpacity(0.60),
                    ],
                    begin: Alignment.topCenter,
                    end: Alignment.bottomCenter,
                  ),
                ),
              ),
            ),
            Positioned.fill(child: CustomPaint(painter: _CardShimmerPainter())),
            Padding(
              padding: const EdgeInsets.all(28),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      _TypeBadge(label: isTruth ? '🤔  TRUTH' : '🔥  DARE'),
                      if (isSpicy) ...[const SizedBox(width: 8), _SpicyBadge()],
                    ],
                  ),
                  const Spacer(),
                  Text(
                    card.content,
                    style: const TextStyle(
                      fontSize: 22,
                      fontWeight: FontWeight.w700,
                      color: Colors.white,
                      height: 1.45,
                      shadows: [
                        Shadow(
                          color: Colors.black54,
                          blurRadius: 8,
                          offset: Offset(0, 2),
                        ),
                      ],
                    ),
                  ).animate().fadeIn(duration: 350.ms),
                  const Spacer(),
                ],
              ),
            ),
            Positioned(
              top: 10,
              left: 12,
              child: Opacity(
                opacity: 0.18,
                child: Text(
                  isTruth ? '🤔' : '🔥',
                  style: const TextStyle(fontSize: 18),
                ),
              ),
            ),
            Positioned(
              bottom: 10,
              right: 12,
              child: Opacity(
                opacity: 0.18,
                child: RotatedBox(
                  quarterTurns: 2,
                  child: Text(
                    isTruth ? '🤔' : '🔥',
                    style: const TextStyle(fontSize: 18),
                  ),
                ),
              ),
            ),
          ],
        ),
      ),
    ).animate().scale(
      begin: const Offset(0.92, 0.92),
      end: const Offset(1, 1),
      duration: 320.ms,
      curve: Curves.easeOutBack,
    );
  }
}

class _CardShimmerPainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final p = Paint()
      ..color = Colors.white.withOpacity(0.025)
      ..strokeWidth = 12
      ..style = PaintingStyle.stroke;
    for (double x = -size.height; x < size.width * 2; x += 38)
      canvas.drawLine(Offset(x, 0), Offset(x + size.height, size.height), p);
  }

  @override
  bool shouldRepaint(_) => false;
}

